        "modelAnswer": "राहुल: नमस्ते समीर! अरे, तुम्हारे हाथ में यह कपड़े का थैला कैसा है? पहले तो तुम हमेशा पॉलिथीन का बैग इस्तेमाल करते थे!\nसमीर: नमस्ते राहुल! हाँ भाई, मैंने अब एकल-उपयोग (सिंगल यूज) प्लास्टिक को पूरी तरह अलविदा कह दिया है। क्या तुमने कल समाचारों में नहीं देखा कि प्लास्टिक कचरा हमारे शहर की नालियों और नदियों को कैसे चोक कर रहा है?\nराहुल: तुमने बिल्कुल सही कहा समीर। कल हमारे विज्ञान के शिक्षक भी बता रहे थे कि प्लास्टिक सैकड़ों वर्षों तक गलता नहीं है और बेजुबान पशु इसे खाकर अपनी जान गँवा रहे हैं।\nसमीर: बिल्कुल! 'स्वच्छ भारत अभियान' केवल सरकार की ज़िम्मेदारी नहीं है, हम छात्रों का भी कर्तव्य है कि अपने घर और विद्यालय से प्लास्टिक का बहिष्कार शुरू करें।\nराहुल: आज से मैं भी प्रण लेता हूँ कि बाज़ार जाते समय कपड़े का थैला साथ रखूँगा और अपनी कॉलोनी के लोगों को भी इसके लिए जागरूक करूँगा।\nसमीर: शाबाश राहुल! जब एक-एक नागरिक जागेगा, तभी हमारा भारत स्वच्छ और सुंदर बनेगा।",
