        "modelAnswer": "परीक्षा भवन,\nनई दिल्ली।\nदिनांक: 15 मार्च 2024\n\nसेवा में,\nश्रीमान अधिशासी अभियंता महोदय,\nराज्य विद्युत वितरण निगम लिमिटेड,\nपश्चिम मंडल, जनकपुरी, नई दिल्ली।\n\nविषय: क्षेत्र में अनधिकृत विद्युत कटौती एवं लो-वोल्टेज की समस्या के निवारण हेतु।\n\nमहोदय,\nसविनय निवेदन है कि मैं जनकपुरी 'बी' ब्लॉक का निवासी हूँ। मैं इस पत्र के माध्यम से हमारे आवासीय क्षेत्र में विगत दो महीनों से जारी अनियमित और भीषण विद्युत कटौती की ओर आपका ध्यान आकृष्ट कराना चाहता हूँ।\n\nहमारे क्षेत्र में प्रतिदिन बिना किसी पूर्व सूचना के 5 से 6 घंटे बिजली गुल रहती है। इसके अतिरिक्त जब बिजली आती भी है, तो वोल्टेज इतना कम होता है कि पंखे, फ्रिज और पानी की मोटरें चलना असंभव हो जाता है। वर्तमान समय में सभी विद्यालयों की वार्षिक परीक्षाएं चल रही हैं। इस अंधकार और गर्मी के कारण विद्यार्थियों का अध्ययन गंभीर रूप से प्रभावित हो रहा है। रात के समय अंधेरा छा जाने से चोरी-डकैती और दुर्घटनाओं का भय भी बना रहता है।\n\nअतः आपसे विनम्र प्रार्थना है कि हमारे क्षेत्र के पुराने और जर्जर ट्रांसफार्मर की जांच करवाकर विद्युत आपूर्ति को शीघ्र सुचारू एवं नियमित करने की कृपा करें, जिससे नागरिकों को राहत मिल सके।\n\nसधन्यवाद।\n\nभवदीय,\nअमन वर्मा\n(सचिव, जनकपुरी रेजिडेंट्स वेलफेयर एसोसिएशन)",
