        "modelAnswer": "सच्चा परोपकार\n\nसड़क के किनारे एक बूढ़ा माली तपती दोपहरी में पसीना बहाते हुए आम का एक नन्हा पौधा रोप रहा था। उसकी कमर झुकी हुई थी और हाथ काँप रहे थे। तभी वहाँ से गुजर रहे एक धनी और घमंडी राहगीर ने रुककर उपहास उड़ाते हुए पूछा, 'अरे बाबा! तुम्हारी उम्र तो कब्र में पाँव लटकाए बैठी है। यह पौधा जब तक वृक्ष बनेगा और फल देगा, तब तक क्या तुम जीवित रहोगे? फिर इस व्यर्थ की मेहनत से तुम्हें क्या हासिल होगा?'\n\nबूढ़े माली ने अपने पसीने से भीगे माथे को पोंछा और एक सहज, करुणामयी मुस्कान के साथ कहा, 'बाबूजी! आज तक मैंने जिन वृक्षों के मीठे और रसीले फल खाए, क्या वे मेरे पुरखों ने केवल अपने लिए लगाए थे? नहीं! उन्होंने लगाए और आनंद मैंने लिया। आज यदि मैं यह पौधा लगा रहा हूँ, तो इसलिए ताकि आने वाली पीढ़ी इसकी शीतल छाँव में विश्राम कर सके और इसके मीठे फल खा सके। जीवन केवल अपने स्वार्थ के लिए जीने का नाम नहीं है, परोपकार ही जीवन का सच्चा धर्म है।'\n\nराहगीर का सिर लज्जा से झुक गया और उसे जीवन का अमूल्य पाठ मिल चुका था।\n\nसीख: सच्चा आनंद स्वार्थ में नहीं, अपितु समाज और भावी पीढ़ी के कल्याण हेतु निस्वार्थ कर्म करने में है।",
